# Let me verify the hypothesis: R=8 kept only if count of L=5s before that position is 0

def check_hypothesis_for_demo():
    """
    Hypothesis: output[r][c] = 2 if (L[c]==5 OR R[c]==8 AND count(L=5 in row r up to pos c-1)==0)
    """
    all_match = True

    for r in range(15):
        row_pred_2 = []  # positions where we predict output should be 2
        row_pred_3 = []  # positions where we predict output should be 3

        # Count L=5s before each position
        l5_count = 0
        for c in range(13):
            left_val = input_demo[r][c]
            right_val = input_demo[r][14+c]
            out_val = output_demo[r][c]

            # Count L=5 before this position (doesn't include current)
            count_before = sum(1 for c2 in range(c) if input_demo[r][c2] == 5)

            # Prediction
            if left_val == 5:
                row_pred_2.append(c)
            elif right_val == 8:
                if count_before == 0:
                    row_pred_2.append(c)
                else:
                    row_pred_3.append(c)
            else:
                row_pred_3.append(c)  # Neither L=5 nor R=8, so default to 3

        # Check
        for c in range(13):
            if out_val == 2:
                if c not in row_pred_2:
                    print(f"R{r}C{c}: output=2 but predicted 3! L={left_val}, R={right_val}, L5_bef={count_before}")
                    all_match = False
            else:
                if c not in row_pred_3:
                    print(f"R{r}C{c}: output=3 but predicted 2! L={left_val}, R={right_val}, L5_bef={count_before}")
                    all_match = False

    if all_match:
        print("Hypothesis VERIFIED for ALL positions in demo!")
        print("\\nBreakdown:")
        print("  output=2 if: L[c]=5 OR (R[c]=8 AND count(L=5 before c) == 0)")
        print("  output=3 otherwise")

