# Final rule implementation:
# - Map L=5 to output=2 at same column
# - Map R=8 to output=2 at same column, BUT filtered (3) if:
#   exactly 1 L=5 AND R8 col == that L5 col + 2
# - Background = 3, pattern = 2

print("Generating output based on my best rule...")
input_rows = input_demo
output_rows = []

for r in range(len(input_rows)):
    output = [3] * 13  # Default background

    # L=5 maps to 2
    for c in range(13):
        if input_rows[r][c] == 5:
            output[c] = 2

    # R=8 maps to 2, unless filtered
    if len([c for c in range(13) if input_rows[r][14+c] == 5]) == 1:
        single_l5_cols = [c for c in range(13) if input_rows[r][c] == 5]
        single_l5_col = single_l5_cols[0]
        for c in range(13):
            if input_rows[r][14+c] == 8:  # R=8 at right col c
                if c == single_l5_col + 2:
                    output[c] = 3  # Filtered
                else:
                    output[c] = 2
    else:
        # Multiple or no L=5, R=8 maps to 2
        for c in range(13):
            if input_rows[r][14+c] == 8:
                output[c] = 2

    output_rows.append(output)

output_demo[:] = output_rows
print("Test output rows:")
for i, row in enumerate(output_demo):
    print(f"Row {i}: {row}")

